pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    if let Some(name) = bytes.strip_prefix("{\"v\":2,\"hello\":\"") {
        if let Some(name) = name.strip_suffix("\"}") {
            return Ok(Msg::Hello(unescape_json(name)?));
        }
    }

    Err("unknown".into())
}

fn unescape_json(value: &str) -> Result<String, String> {
    let mut result = String::new();
    let mut escaped = false;
    for character in value.chars() {
        if escaped {
            match character {
                '\\' => result.push('\\'),
                '"' => result.push('"'),
                'n' => result.push('\n'),
                'r' => result.push('\r'),
                't' => result.push('\t'),
                _ => return Err("unknown".into()),
            }
            escaped = false;
        } else if character == '\\' {
            escaped = true;
        } else {
            result.push(character);
        }
    }
    if escaped {
        return Err("unknown".into());
    }
    Ok(result)
}

fn escape_json(value: &str) -> String {
    value
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("{{\"v\":2,\"hello\":\"{}\"}}", escape_json(name)),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    fn encode_roundtrip(msg: &Msg) -> Result<Msg, String> {
        decode(&encode(msg))
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(encode_roundtrip(&Msg::Ping), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_v2_encode_roundtrip() {
        let msg = Msg::Hello("Ada".into());
        assert_eq!(encode(&msg), r#"{"v":2,"hello":"Ada"}"#);
        assert!(matches!(encode_roundtrip(&msg), Ok(Msg::Hello(name)) if name == "Ada"));
    }
}
